export LANG=C LC_ALL=C
D=/opt/lzh/v7re/work/hclkall
rm -rf $D; mkdir -p $D; cd $D || exit 1
cat > /tmp/ha.b64 <<'B64'

B64
base64 -d /tmp/ha.b64 > /tmp/ha.tgz && tar xzf /tmp/ha.tgz -C $D
cd $D
ls *.tcl | sed 's/.tcl//' | xargs -P 14 -I{} bash -c '/opt/lzh/Xilinx/Vivado/2017.2/bin/vivado -mode batch -notrace -source {}.tcl > {}.log 2>&1'
ok=0
for t in $(ls *.tcl | sed 's/.tcl//'); do
  if grep -q "DONE_$t" $t.log 2>/dev/null; then ok=$((ok+1)); else echo "FAIL $t :: $(grep -m1 'ERROR:' $t.log | cut -c1-150)"; fi
done
echo "OK=$ok"
cd $D && tar czf /tmp/hclkall_out.tgz *.bit *.pips 2>/dev/null
echo HADONE
